import re

LUN = re.compile(r'^LOGICAL UNIT NUMBER\s+(?P<lun>\S+)\s*$')
PROMPT = re.compile(r'(?i)(^\S.*>\s*\S*naviseccli)|^\s*naviseccli\b')
EQ = re.compile(r'^(?P<key>[^=]+?)\s*=\s*(?P<value>.*?)\s*$')
COLON = re.compile(r'^(?P<key>[^\s:=]+(?: [^\s:=]+)*):(?:\s+(?P<value>.*?))?\s*$')
SPACED = re.compile(r'^(?P<key>\S+(?: \S+)*)\s{2,}(?P<value>\S.*?)\s*$')

def msg_key(text, rec):
    if re.match(r'(?i)read cache configured', text):
        base = 'Read cache configuration'
    else:
        base = 'Message'
    key = base
    n = 2
    while key in rec:
        key = base + ' ' + str(n)
        n += 1
    return key

def parse(lines):
    blocks = []
    skip = []
    cur = None
    msg = None
    def flush():
        if cur is not None:
            blocks.append({'name': 'lun', 'kind': 'kv', 'lines': cur['lines'], 'records': [cur['rec']]})
    for i, line in enumerate(lines):
        if not line.strip():
            msg = None
            continue
        if PROMPT.search(line):
            skip.append(i)
            msg = None
            continue
        m = LUN.match(line)
        if m:
            flush()
            cur = {'lines': [i], 'rec': {'LOGICAL UNIT NUMBER': m.group('lun')}}
            msg = None
            continue
        if cur is None:
            skip.append(i)
            continue
        if msg is not None and line[:1].isspace():
            cur['rec'][msg] = (cur['rec'][msg] + ' ' + line.strip()).strip()
            cur['lines'].append(i)
            continue
        m = COLON.match(line)
        if not m:
            m = EQ.match(line) if '=' in line else None
        if not m:
            m = SPACED.match(line)
        if m:
            cur['rec'][m.group('key').strip()] = (m.group('value') or '').strip()
            cur['lines'].append(i)
            msg = None
        else:
            text = line.strip()
            msg = msg_key(text, cur['rec'])
            cur['rec'][msg] = text
            cur['lines'].append(i)
    flush()
    return {'blocks': blocks, 'skip': skip}
